"""Counting words in text."""

from __future__ import annotations

import heapq
import re
from collections import Counter

WORD = re.compile(r"[a-z]+(?:'[a-z]+)?")


def words(text: str) -> list[str]:
    """Lower-cased words in text; an apostrophe inside a word, as in "it's", is kept."""
    return WORD.findall(text.lower())


def count_words(text: str) -> Counter[str]:
    """How many times each word appears in text."""
    return Counter(words(text))


def unique_words(text: str) -> int:
    """Number of different words in text."""
    return len(set(words(text)))


def top_words(counts: Counter[str], n: int) -> list[tuple[str, int]]:
    """The n most common words, most common first, ties in alphabetical order."""
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:n]

